import { useEffect, useId, useRef, useState } from 'react';
import type {
  ButtonHTMLAttributes,
  CSSProperties,
  HTMLAttributes,
  InputHTMLAttributes,
  KeyboardEvent,
  MouseEvent,
  ReactNode,
  SVGProps,
} from 'react';
import { ArrowUp, ChevronRight, Square } from 'lucide-react';
import { GLYPHS, GLYPH_STROKE, type IconName } from './icons';

export type { IconName } from './icons';
export const iconNames = Object.keys(GLYPHS) as IconName[];

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

/* Icon: the DROIDEX set (packages/icons) ---------------------------------- */

export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'ref' | 'children' | 'name'> {
  name: IconName;
  /** 16 in controls and rows (icon-md), 14 beside small text (icon-sm). */
  size?: number;
}

export function Icon({
  name,
  size = 16,
  strokeWidth,
  'aria-label': ariaLabel,
  className,
  ...rest
}: IconProps) {
  const labelled = Boolean(ariaLabel);
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth ?? GLYPH_STROKE[name] ?? 1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      role={labelled ? 'img' : undefined}
      aria-label={ariaLabel}
      aria-hidden={labelled ? undefined : true}
      data-icon={name}
      className={cx('ds-icon', className)}
      {...rest}
      dangerouslySetInnerHTML={{ __html: GLYPHS[name] }}
    />
  );
}

/** The set's spinner, turning at the app's calm 1.8s. */
export function Spinner({ size = 16, className }: { size?: number; className?: string }) {
  return <Icon name="spinner" size={size} className={cx('ds-spin-slow', className)} />;
}

type IconInput = IconName | ReactNode;
function renderIcon(icon: IconInput, size = 16) {
  return typeof icon === 'string' ? <Icon name={icon as IconName} size={size} /> : icon;
}

/* Button ------------------------------------------------------------------ */

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'success';
export type ButtonSize = 'sm' | 'md' | 'lg';

interface ButtonBaseProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  shape?: 'default' | 'round';
  /** An icon name from the DROIDEX set ("git-branch"), or a ready glyph. */
  icon?: IconInput;
  /** Swaps the icon (or the label) for a spinner and keeps the width. */
  loading?: boolean;
}

// Icon-only buttons have no visible label, so they must name themselves.
export type ButtonProps = ButtonBaseProps &
  (
    | { children: ReactNode; icon?: IconInput }
    | { children?: undefined; icon: IconInput; 'aria-label': string }
  );

export function Button({
  variant = 'secondary',
  size = 'md',
  shape = 'default',
  icon,
  loading = false,
  type = 'button',
  className,
  children,
  ...props
}: ButtonProps) {
  const iconOnly = children === undefined;
  const labelHidden = loading && icon === undefined;
  const spinner = <Icon name="spinner" className="ds-spin" />;
  return (
    <button
      type={type}
      aria-busy={loading || undefined}
      data-loading={loading || undefined}
      {...props}
      className={cx(
        'ds-button',
        'ds-button-' + variant,
        'ds-button-' + size,
        iconOnly && 'ds-button-icon',
        shape === 'round' && 'ds-button-round',
        className,
      )}
    >
      {icon !== undefined && (
        <span className="ds-button-glyph" aria-hidden="true">
          {loading ? spinner : renderIcon(icon)}
        </span>
      )}
      {!iconOnly && <span className={cx('ds-button-label', labelHidden && 'ds-invisible')}>{children}</span>}
      {labelHidden && <span className="ds-button-spinner">{spinner}</span>}
    </button>
  );
}

/* Badge ------------------------------------------------------------------- */

export type BadgeTone = 'neutral' | 'success' | 'warning' | 'danger' | 'accent';

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  tone?: BadgeTone;
  /** A 12px icon, for the states people scan for. */
  icon?: IconName;
  /** Uppercase mode badge such as SPEC or AGI. */
  overline?: boolean;
  /** Always a word: colour never carries the state alone. */
  children: ReactNode;
}

export function Badge({ tone = 'neutral', icon, overline = false, className, children, ...props }: BadgeProps) {
  return (
    <span {...props} className={cx('ds-badge', 'ds-badge-' + tone, overline && 'ds-badge-overline', className)}>
      {icon !== undefined && <Icon name={icon} size={12} />}
      {children}
    </span>
  );
}

/* Card -------------------------------------------------------------------- */

export interface CardProps extends HTMLAttributes<HTMLDivElement> {
  /** Adds the floating shadow, for cards that sit over other content. */
  floating?: boolean;
}

export function Card({ floating = false, className, ...props }: CardProps) {
  return <div {...props} className={cx('ds-card', floating && 'ds-card-floating', className)} />;
}

/* Input ------------------------------------------------------------------- */

export interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  hint?: ReactNode;
  /** Says how to fix the value; replaces the hint and marks the field invalid. */
  error?: ReactNode;
  /** 32px field with 13px text, for toolbars and pickers. */
  compact?: boolean;
  /** Keeps the label for assistive technology only, such as a search field. */
  hideLabel?: boolean;
  /** A leading 14px icon, such as "search". */
  icon?: IconName;
}

export function Input({ label, hint, error, compact = false, hideLabel = false, icon, id, className, ...props }: InputProps) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const noteId = inputId + '-note';
  const note = error ?? hint;
  const invalid = error !== undefined;
  const input = (
    <input
      {...props}
      id={inputId}
      aria-describedby={note !== undefined ? noteId : undefined}
      aria-invalid={invalid || undefined}
      className={cx('ds-input', compact && 'ds-input-compact', icon && 'ds-input-affixed', className)}
    />
  );
  return (
    <div className="ds-field">
      <label htmlFor={inputId} className={cx('ds-field-label', hideLabel && 'ds-sr-only')}>
        {label}
      </label>
      {icon ? (
        <div className="ds-input-wrap">
          <Icon name={icon} size={14} className="ds-input-icon" />
          {input}
        </div>
      ) : (
        input
      )}
      {note !== undefined && (
        <p id={noteId} className={invalid ? 'ds-field-error' : 'ds-field-hint'}>
          {note}
        </p>
      )}
    </div>
  );
}

/* Switch ------------------------------------------------------------------ */

export interface SwitchProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange'> {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  label: string;
  description?: ReactNode;
}

export function Switch({ checked, onCheckedChange, label, description, className, ...props }: SwitchProps) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      {...props}
      className={cx('ds-switch', className)}
      onClick={() => onCheckedChange(!checked)}
    >
      <span className="ds-switch-text">
        <span className="ds-switch-label">{label}</span>
        {description !== undefined && <span className="ds-switch-description">{description}</span>}
      </span>
      <span className="ds-switch-track" aria-hidden="true">
        <span className="ds-switch-thumb" />
      </span>
    </button>
  );
}

/* Tabs: a segmented control ------------------------------------------------ */

export interface TabItem {
  value: string;
  label: string;
  content: ReactNode;
  disabled?: boolean;
}

export interface TabsProps {
  label: string;
  items: TabItem[];
  value: string;
  onValueChange: (value: string) => void;
}

export function Tabs({ label, items, value, onValueChange }: TabsProps) {
  const id = useId();
  return (
    <div className="ds-tabs">
      <div role="tablist" aria-label={label} className="ds-tablist">
        {items.map((item, index) => (
          <button
            key={item.value}
            type="button"
            role="tab"
            id={id + '-tab-' + index}
            aria-controls={id + '-panel-' + index}
            aria-selected={value === item.value}
            disabled={item.disabled}
            tabIndex={value === item.value ? 0 : -1}
            className="ds-tab"
            onClick={() => onValueChange(item.value)}
            onKeyDown={(event) => {
              if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
              event.preventDefault();
              const enabled = items.map((tab, i) => ({ tab, i })).filter(({ tab }) => !tab.disabled);
              const current = enabled.findIndex(({ i }) => i === index);
              let next = current;
              if (event.key === 'Home') next = 0;
              if (event.key === 'End') next = enabled.length - 1;
              if (event.key === 'ArrowRight') next = (current + 1) % enabled.length;
              if (event.key === 'ArrowLeft') next = (current - 1 + enabled.length) % enabled.length;
              const target = enabled[next];
              if (!target) return;
              document.getElementById(id + '-tab-' + target.i)?.focus();
              onValueChange(target.tab.value);
            }}
          >
            {item.label}
          </button>
        ))}
      </div>
      {items.map((item, index) => (
        <div
          key={item.value}
          role="tabpanel"
          id={id + '-panel-' + index}
          aria-labelledby={id + '-tab-' + index}
          hidden={value !== item.value}
          tabIndex={0}
          className="ds-tabpanel"
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}

/* Dialog ------------------------------------------------------------------ */

export interface DialogProps {
  open: boolean;
  onClose: () => void;
  title: string;
  description?: ReactNode;
  /** confirm 440px, form 560px, content 720px. */
  size?: 'confirm' | 'form' | 'content';
  /** Bottom-right buttons: primary last, a danger action on the left. */
  actions?: ReactNode;
  children?: ReactNode;
}

const FOCUSABLE = 'a[href], button, input, select, textarea, summary, [tabindex], [contenteditable="true"]';

function isFocusable(element: HTMLElement) {
  return (
    element.isConnected &&
    element.getClientRects().length > 0 &&
    getComputedStyle(element).visibility !== 'hidden' &&
    !element.closest('[inert]') &&
    element.tabIndex >= 0 &&
    !element.matches(':disabled')
  );
}

export function Dialog({ open, onClose, title, description, size = 'form', actions, children }: DialogProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();
  const descriptionId = useId();
  useEffect(() => {
    const dialog = ref.current;
    if (!open || !dialog) return;
    const previous = document.activeElement;
    dialog.showModal();
    return () => {
      dialog.close();
      if (previous instanceof HTMLElement && isFocusable(previous)) previous.focus();
    };
  }, [open]);
  return (
    <dialog
      ref={ref}
      aria-labelledby={titleId}
      aria-describedby={description !== undefined ? descriptionId : undefined}
      className={cx('ds-dialog', 'ds-dialog-' + size)}
      onKeyDown={(event) => {
        if (event.key !== 'Tab') return;
        // Native Tab can leave the preview iframe while its modal stays open.
        const dialog = event.currentTarget;
        const focusable = [...dialog.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(isFocusable);
        const position = focusable.findIndex((element) => element === document.activeElement);
        if (focusable.length === 0) return;
        if (position !== -1 && (event.shiftKey ? position !== 0 : position !== focusable.length - 1)) return;
        event.preventDefault();
        (event.shiftKey ? focusable.at(-1) : focusable[0])?.focus();
      }}
      onCancel={(event) => {
        event.preventDefault();
        onClose();
      }}
    >
      <div className="ds-dialog-header">
        <div className="ds-dialog-heading">
          <h2 id={titleId} className="ds-heading">
            {title}
          </h2>
          {description !== undefined && (
            <p id={descriptionId} className="ds-dialog-description">
              {description}
            </p>
          )}
        </div>
        <Button variant="ghost" size="sm" className="ds-dialog-close" icon="x" aria-label="Close dialog" onClick={onClose} />
      </div>
      {children !== undefined && <div className="ds-dialog-body">{children}</div>}
      {actions !== undefined && <div className="ds-dialog-actions">{actions}</div>}
    </dialog>
  );
}

/* Row and SectionHeader (ui/Row) ------------------------------------------- */

interface RowBaseProps extends Omit<HTMLAttributes<HTMLElement>, 'onClick'> {
  /** A 16px icon name or glyph. null keeps the empty icon column so labels line up. */
  icon?: IconInput | null;
  label: ReactNode;
  /** Short trailing meta: a count, a timestamp, a state. */
  meta?: ReactNode;
  trailing?: ReactNode;
}

// Without an action the row is a readout, not a control.
export type RowProps = RowBaseProps &
  (
    | { onClick: (event: MouseEvent<HTMLButtonElement>) => void; active?: boolean; disabled?: boolean }
    | { onClick?: undefined; active?: never; disabled?: never }
  );

export function Row({ icon, label, meta, trailing, active = false, disabled = false, onClick, className, ...props }: RowProps) {
  const content = (
    <>
      {icon !== undefined && (
        <span className="ds-row-icon" aria-hidden="true">
          {icon === null ? null : renderIcon(icon)}
        </span>
      )}
      <span className="ds-row-label">{label}</span>
      {meta !== undefined && <span className="ds-row-meta">{meta}</span>}
      {trailing}
    </>
  );
  if (!onClick) {
    return (
      <div {...props} className={cx('ds-row', className)}>
        {content}
      </div>
    );
  }
  return (
    <button
      type="button"
      disabled={disabled}
      aria-current={active || undefined}
      data-active={active || undefined}
      {...props}
      onClick={onClick}
      className={cx('ds-row', 'ds-row-button', className)}
    >
      {content}
    </button>
  );
}

export interface SectionHeaderProps extends HTMLAttributes<HTMLDivElement> {
  label: ReactNode;
  /** A trailing caption, aligned on the label's baseline. */
  trailing?: ReactNode;
}

export function SectionHeader({ label, trailing, className, ...props }: SectionHeaderProps) {
  return (
    <div {...props} className={cx('ds-section-header', className)}>
      <span className="ds-section-header-label">{label}</span>
      {trailing !== undefined && <span className="ds-section-header-trailing">{trailing}</span>}
    </div>
  );
}

/* Menu -------------------------------------------------------------------- */

export interface MenuProps extends HTMLAttributes<HTMLDivElement> {
  label: string;
  /** Escape calls it; return focus to the trigger there. */
  onClose?: () => void;
  /** Focus the first item on mount, as when the menu opens from a trigger. */
  autoFocus?: boolean;
}

function menuItems(menu: HTMLElement) {
  return [...menu.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:not(:disabled)')];
}

export function Menu({ label, onClose, autoFocus = false, className, children, onKeyDown, ...props }: MenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (autoFocus && ref.current) menuItems(ref.current)[0]?.focus();
  }, [autoFocus]);
  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.key === 'Escape' && onClose) {
      event.preventDefault();
      onClose();
      return;
    }
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
    const items = menuItems(event.currentTarget);
    if (items.length === 0) return;
    event.preventDefault();
    const current = items.findIndex((item) => item === document.activeElement);
    let next = 0;
    if (event.key === 'ArrowDown') next = current < 0 ? 0 : (current + 1) % items.length;
    if (event.key === 'ArrowUp') next = current < 0 ? items.length - 1 : (current - 1 + items.length) % items.length;
    if (event.key === 'End') next = items.length - 1;
    items[next]?.focus();
  }
  return (
    <div ref={ref} role="menu" aria-label={label} {...props} onKeyDown={handleKeyDown} className={cx('ds-menu', className)}>
      {children}
    </div>
  );
}

export interface MenuGroupProps extends HTMLAttributes<HTMLDivElement> {
  label?: string;
}

// Groups separate by space, never a divider.
export function MenuGroup({ label, className, children, ...props }: MenuGroupProps) {
  const labelId = useId();
  return (
    <div role="group" aria-labelledby={label !== undefined ? labelId : undefined} {...props} className={cx('ds-menu-group', className)}>
      {label !== undefined && (
        <div id={labelId} className="ds-menu-label">
          {label}
        </div>
      )}
      {children}
    </div>
  );
}

export interface MenuItemProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onSelect'> {
  icon?: IconInput;
  /** A caption under the label, as in the autonomy and model menus. */
  description?: ReactNode;
  shortcut?: string;
  /** The chosen option: a trailing check. */
  selected?: boolean;
  /** Destructive: danger text at rest, danger-soft fill on hover. Put it last. */
  danger?: boolean;
  onSelect?: () => void;
}

export function MenuItem({
  icon,
  description,
  shortcut,
  selected = false,
  danger = false,
  onSelect,
  className,
  children,
  ...props
}: MenuItemProps) {
  const [blink, setBlink] = useState<'off' | 'on' | null>(null);
  const timers = useRef<number[]>([]);
  useEffect(() => () => timers.current.forEach((timer) => window.clearTimeout(timer)), []);
  // The macOS select blink: highlight off 90ms, on 90ms, then act.
  function select() {
    if (blink !== null) return;
    setBlink('off');
    timers.current.push(window.setTimeout(() => setBlink('on'), 90));
    timers.current.push(
      window.setTimeout(() => {
        setBlink(null);
        onSelect?.();
      }, 180),
    );
  }
  return (
    <button
      type="button"
      role="menuitem"
      tabIndex={-1}
      data-blink={blink ?? undefined}
      data-danger={danger || undefined}
      data-described={description !== undefined || undefined}
      aria-checked={selected || undefined}
      {...props}
      onClick={select}
      className={cx('ds-menu-item', className)}
    >
      {icon !== undefined && (
        <span className="ds-menu-item-icon" aria-hidden="true">
          {renderIcon(icon)}
        </span>
      )}
      <span className="ds-menu-item-text">
        <span className="ds-menu-item-label">{children}</span>
        {description !== undefined && <span className="ds-menu-item-description">{description}</span>}
      </span>
      {shortcut !== undefined && <span className="ds-menu-item-shortcut">{shortcut}</span>}
      {selected && <Icon name="check" size={14} className="ds-menu-item-check" />}
    </button>
  );
}

/* Kbd --------------------------------------------------------------------- */

export function Kbd({ className, ...props }: HTMLAttributes<HTMLElement>) {
  return <kbd {...props} className={cx('ds-kbd', className)} />;
}

/* Toast ------------------------------------------------------------------- */

export type ToastTone = 'info' | 'success' | 'warning' | 'danger' | 'update' | 'loading';

export interface ToastProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  tone?: ToastTone;
  /** The result in a few words: "Pushed to remote". */
  title: string;
  /** One line on why, or what to do next. */
  description?: string;
  action?: { label: string; onClick: () => void };
  onClose?: () => void;
}

const TOAST_ICON: Partial<Record<ToastTone, IconName>> = {
  success: 'circle-check',
  danger: 'circle-alert',
  warning: 'alert-triangle',
  update: 'circle-arrow-up',
  loading: 'spinner',
};

export function Toast({ tone = 'info', title, description, action, onClose, className, ...props }: ToastProps) {
  const icon = TOAST_ICON[tone];
  return (
    <div role={tone === 'danger' ? 'alert' : 'status'} {...props} className={cx('ds-toast', className)}>
      {icon && <Icon name={icon} className={cx('ds-toast-icon', 'ds-toast-icon-' + tone, tone === 'loading' && 'ds-spin-slow')} />}
      <div className="ds-toast-body">
        <p className="ds-toast-title">{title}</p>
        {description !== undefined && <p className="ds-toast-description">{description}</p>}
      </div>
      {action !== undefined && (
        <button type="button" className="ds-toast-action" onClick={action.onClick}>
          {action.label}
        </button>
      )}
      {onClose !== undefined && (
        <button type="button" className="ds-toast-close" aria-label="Dismiss" onClick={onClose}>
          <Icon name="x" size={14} />
        </button>
      )}
    </div>
  );
}

/* Brand ------------------------------------------------------------------- */

/** The DROIDEX wordmark: Silkscreen, -0.04em, DROIDE + X. It carries no colour of its own. */
export function BrandMark({ size = 32, className, style }: { size?: number; className?: string; style?: CSSProperties }) {
  return (
    <span
      role="img"
      aria-label="DROIDEX"
      className={cx('ds-brandmark', className)}
      style={{ fontSize: size, letterSpacing: (size * -0.04).toFixed(2) + 'px', ...style }}
    >
      <span aria-hidden="true">
        DROIDE<span className="ds-brandmark-x">X</span>
      </span>
    </span>
  );
}

const D_CELLS = [
  [72, 312], [152, 312], [232, 312], [312, 312], [72, 392], [392, 392], [72, 472],
  [392, 472], [72, 552], [392, 552], [72, 632], [152, 632], [232, 632], [312, 632],
];
const X_CELLS = [
  [552, 312], [872, 312], [632, 392], [792, 392], [712, 472], [632, 552], [792, 552], [552, 632], [872, 632],
];

/** The DX app icon from assets/brand on its 80px grid. Never redraw or recolour it. */
export function AppIcon({ size = 32, tile = 'ink', className }: { size?: number; tile?: 'ink' | 'paper'; className?: string }) {
  const tileFill = tile === 'ink' ? 'var(--ds-brand-ink)' : 'var(--ds-brand-paper)';
  const dFill = tile === 'ink' ? 'var(--ds-brand-paper)' : 'var(--ds-brand-ink)';
  return (
    <svg width={size} height={size} viewBox="0 0 1024 1024" role="img" aria-label="DROIDEX" className={className}>
      <rect width="1024" height="1024" rx="228" fill={tileFill} />
      <g fill={dFill}>
        {D_CELLS.map(([x, y]) => (
          <rect key={'d' + x + '-' + y} x={x} y={y} width="80" height="80" />
        ))}
      </g>
      <g fill="var(--ds-brand)">
        {X_CELLS.map(([x, y]) => (
          <rect key={'x' + x + '-' + y} x={x} y={y} width="80" height="80" />
        ))}
      </g>
    </svg>
  );
}

/* Model and harness marks (components/ModelIcon) --------------------------- */

export type Provider = 'factory' | 'anthropic' | 'claude' | 'openai' | 'google';

const MARKS: Record<Provider, { viewBox: string; tone?: string; paths: Array<{ d: string; fill?: string }> }> = {
  factory: {
    viewBox: '0 0 67 65',
    tone: 'var(--ds-fg)',
