/** The maker or harness mark beside a model name: 14px in rows and chips. */
export function ModelIcon({ provider, size = 14, muted = false }: { provider: Provider; size?: number; muted?: boolean }) {
  const mark = MARKS[provider];
  return (
    <svg
      width={size}
      height={size}
      viewBox={mark.viewBox}
      aria-hidden="true"
      className="ds-model-icon"
      style={{ color: muted ? 'var(--ds-fg-muted)' : mark.tone }}
    >
      {mark.paths.map((path) => (
        <path key={path.d.slice(0, 24)} d={path.d} fill={muted ? 'currentColor' : (path.fill ?? 'currentColor')} />
      ))}
    </svg>
  );
}

/* Status glyph (ActivityStatusGlyph) --------------------------------------- */

export type SessionStatus = 'working' | 'waiting' | 'approval' | 'reply' | 'failed' | 'interrupted' | 'ready' | 'settled';

const STATUS: Record<SessionStatus, { label: string; tone: string; shape: ReactNode }> = {
  working: { label: 'Working', tone: 'var(--ds-fg)', shape: <><circle cx="8" cy="8" r="6" /><circle cx="8" cy="8" r="2" fill="currentColor" stroke="none" /></> },
  waiting: { label: 'Waiting', tone: 'var(--ds-fg-muted)', shape: <><circle cx="8" cy="8" r="6" /><path d="M8 4.5V8l2.5 1.5" /></> },
  approval: { label: 'Needs approval', tone: 'var(--ds-warning)', shape: <><circle cx="8" cy="8" r="6" /><path d="M8 4.5V8l2.5 1.5" /></> },
  reply: { label: 'Replied', tone: 'var(--ds-accent)', shape: <><circle cx="8" cy="8" r="6" /><path d="M8 2a6 6 0 0 1 0 12z" fill="currentColor" stroke="none" /></> },
  failed: { label: 'Failed', tone: 'var(--ds-danger)', shape: <><circle cx="8" cy="8" r="6" /><path d="M6 6l4 4M10 6l-4 4" /></> },
  interrupted: { label: 'Interrupted', tone: 'var(--ds-warning)', shape: <><circle cx="8" cy="8" r="6" /><path d="M6.5 5.5v5M9.5 5.5v5" /></> },
  ready: { label: 'Ready', tone: 'var(--ds-fg-muted)', shape: <circle cx="8" cy="8" r="6" strokeDasharray="2.6 2.4" /> },
  settled: { label: 'Settled', tone: 'var(--ds-positive)', shape: <><circle cx="8" cy="8" r="6" fill="currentColor" stroke="none" /><path d="M5.5 8.2l1.8 1.8L10.7 6.5" stroke="var(--ds-canvas)" /></> },
};

/** One 14px stroke family for a chat's state, tinted by urgency. */
export function StatusGlyph({ status, decorative = false }: { status: SessionStatus; decorative?: boolean }) {
  const s = STATUS[status];
  return (
    <svg
      viewBox="0 0 16 16"
      width={14}
      height={14}
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      role={decorative ? undefined : 'img'}
      aria-hidden={decorative || undefined}
      aria-label={decorative ? undefined : s.label}
      style={{ color: s.tone, flexShrink: 0 }}
    >
      {s.shape}
    </svg>
  );
}

/* Transcript: disclosure ------------------------------------------------- */

/** Trails a row's label; shows on hover, focus or open, and its box is always laid out. */
export function Caret({ open, always = false }: { open: boolean; always?: boolean }) {
  return (
    <ChevronRight
      size={14}
      strokeWidth={1.5}
      aria-hidden="true"
      className="ds-caret"
      data-open={open || undefined}
      data-always={always || undefined}
    />
  );
}

/** Expand through grid rows (240ms smooth-out) with a 6px settle; never measured heights. */
export function Expand({ open, children }: { open: boolean; children: ReactNode }) {
  return (
    <div className="ds-expand" data-open={open || undefined} aria-hidden={!open} inert={!open ? true : undefined}>
      <div className="ds-expand-inner">{children}</div>
    </div>
  );
}

/** The tone-separated panel that holds an expanded tool or diff body. */
export function ToolPanel({ className, children }: { className?: string; children: ReactNode }) {
  return <div className={cx('ds-tool-panel', className)}>{children}</div>;
}

/* Transcript: tool lines ---------------------------------------------------- */

function splitPath(path: string) {
  const cut = path.lastIndexOf('/');
  return cut < 0 ? { dir: '', name: path } : { dir: path.slice(0, cut + 1), name: path.slice(cut + 1) };
}

export interface ToolLineProps {
  /** Settled verb: Read, Edited, Searched, Ran, Listed, Fetched. */
  verb: string;
  /** Live verb, shimmering while running: Reading, Searching. */
  liveVerb?: string;
  running?: boolean;
  /** A path (dir dims, file name reads) or a plain object such as a query. */
  target?: string;
  /** Where it ran, after a middle dot: "· browser", "· MCP linear". */
  source?: string;
  status?: 'error' | 'interrupted';
  defaultOpen?: boolean;
  /** The expanded body, usually a ToolCallCard or CommandCard. */
  children?: ReactNode;
}

/** One sentence per tool call. No icon and no box: the verb, then what it touched. */
export function ToolLine({ verb, liveVerb, running = false, target, source, status, defaultOpen = false, children }: ToolLineProps) {
  const [open, setOpen] = useState(defaultOpen);
  const expandable = children !== undefined;
  const isPath = target !== undefined && target.includes('/');
  const parts = target !== undefined && isPath ? splitPath(target) : null;
  const sentence = (
    <>
      {running ? <span className="ds-shimmer ds-tool-live">{liveVerb ?? verb}</span> : <span className="ds-tool-verb">{verb}</span>}
      {target !== undefined && (
        <span className="ds-tool-target" title={target}>
          {parts ? (
            <>
              <span className="ds-tool-dir">{parts.dir}</span>
              <span className="ds-tool-name">{parts.name}</span>
            </>
          ) : (
            <span className="ds-tool-name">{target}</span>
          )}
        </span>
      )}
      {source !== undefined && <span className="ds-tool-source">· {source}</span>}
      {expandable && <Caret open={open} />}
    </>
  );
  return (
    <div className="ds-tool">
      <div className="ds-tool-line">
        {expandable ? (
          <button type="button" className="ds-tool-toggle" aria-expanded={open} onClick={() => setOpen((v) => !v)}>
            {sentence}
          </button>
        ) : (
          <span className="ds-tool-toggle">{sentence}</span>
        )}
        {status === 'error' && <Badge tone="danger">Error</Badge>}
        {status === 'interrupted' && <Badge>Interrupted</Badge>}
      </div>
      {expandable && (
        <Expand open={open}>
          <div className="ds-tool-body">{children}</div>
        </Expand>
      )}
    </div>
  );
}

/** A tool's arguments and output in mono, inside the ToolPanel. */
export function ToolCallCard({ args, output, error = false }: { args?: string; output?: string; error?: boolean }) {
  return (
    <ToolPanel>
      <div className="ds-tool-card">
        {args !== undefined && <pre className="ds-tool-args">{args}</pre>}
        {output !== undefined && <pre className={cx('ds-tool-output', error && 'ds-tool-output-error')}>{output}</pre>}
      </div>
    </ToolPanel>
  );
}

/** A shell command: a muted $ prompt, the command, then its output. */
export function CommandCard({ command, output, error = false }: { command: string; output?: string; error?: boolean }) {
  return (
    <ToolPanel>
      <div className="ds-tool-card">
        <pre className="ds-tool-args">
          <span className="ds-tool-prompt">$ </span>
          {command}
        </pre>
        {output !== undefined && <pre className={cx('ds-tool-output', error && 'ds-tool-output-error')}>{output}</pre>}
      </div>
    </ToolPanel>
  );
}

function fileIcon(path: string): IconName {
  if (/\.(png|jpe?g|gif|svg|webp)$/i.test(path)) return 'file-image';
  if (/\.(md|txt|mdx)$/i.test(path)) return 'file-text';
  if (/\.(csv|xlsx?)$/i.test(path)) return 'file-spreadsheet';
  if (/\.(json|ya?ml|toml|lock)$/i.test(path)) return 'file-cog';
  if (/\.(zip|tar|gz)$/i.test(path)) return 'file-archive';
  return 'file';
}

/** The files a tool touched: four chips, then a "+N more" fold. */
export function FileChips({ files, limit = 4 }: { files: string[]; limit?: number }) {
  const [all, setAll] = useState(false);
  const shown = all ? files : files.slice(0, limit);
  const hidden = files.length - shown.length;
  return (
    <div className="ds-file-rail">
      {shown.map((file) => (
        <button key={file} type="button" className="ds-file-chip" title={file}>
          <Icon name={fileIcon(file)} size={14} />
          <span className="ds-file-chip-name">{splitPath(file).name}</span>
        </button>
      ))}
      {hidden > 0 && (
        <button type="button" className="ds-file-chip" onClick={() => setAll(true)}>
          +{hidden} more
        </button>
      )}
    </div>
  );
}

/* Transcript: thinking, working, worked ------------------------------------- */

export function ThinkingLine({ duration, active = false, defaultOpen = false, children }: { duration?: string; active?: boolean; defaultOpen?: boolean; children?: ReactNode }) {
  const [open, setOpen] = useState(defaultOpen);
  const label = active ? 'Thinking' + (duration ? ' ' + duration : '') : duration ? 'Thought for ' + duration : 'Thought';
  return (
    <div className="ds-tool">
      <button type="button" className="ds-tool-line ds-tool-toggle" aria-expanded={open} onClick={() => setOpen((v) => !v)}>
        <span className={active ? 'ds-shimmer ds-tool-live' : 'ds-thinking-label'}>{label}</span>
        {children !== undefined && <Caret open={open} />}
      </button>
      {children !== undefined && (
        <Expand open={open}>
          <div className="ds-thinking-body">{children}</div>
        </Expand>
      )}
    </div>
  );
}

/** One shimmer label in a fixed 20px line box: "Working 12s…". */
export function WorkingIndicator({ label = 'Working', elapsed }: { label?: string; elapsed?: string }) {
  return (
    <div className="ds-working">
      <span className="ds-shimmer ds-tool-live">
        <span aria-live="polite">{label}</span>
        <span aria-hidden="true">{elapsed ? ' ' + elapsed : ''}…</span>
      </span>
    </div>
  );
}

/** The finished turn's steps, folded behind "Worked for 1m 12s" above the reply. */
export function WorkedGroup({ duration, defaultOpen = false, children }: { duration: string; defaultOpen?: boolean; children: ReactNode }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="ds-worked">
      <button type="button" className="ds-worked-toggle" aria-expanded={open} onClick={() => setOpen((v) => !v)}>
        Worked for {duration}
        <Caret open={open} always />
      </button>
      <Expand open={open}>
        <div className="ds-worked-body">{children}</div>
      </Expand>
    </div>
  );
}

/* Transcript: diffs --------------------------------------------------------- */

export function ChangeCount({ tone, value }: { tone: 'add' | 'del'; value: number }) {
  return (
    <span className={'ds-change-count ds-change-' + tone}>
      {tone === 'add' ? '+' : '−'}
      {value}
    </span>
  );
}

export type DiffOp = { type: 'add' | 'del' | 'ctx'; text: string };

export function DiffLines({ ops }: { ops: DiffOp[] }) {
  return (
    <div className="ds-diff-lines">
      {ops.map((op, i) => (
        <div key={op.type + i} className={'ds-diff-row ds-diff-' + op.type}>
          <span className="ds-diff-sign">{op.type === 'add' ? '+' : op.type === 'del' ? '−' : ''}</span>
          <span className="ds-diff-text">{op.text || ' '}</span>
        </div>
      ))}
    </div>
  );
}

export interface DiffCardProps {
  verb?: 'Edit' | 'Create' | 'Patch';
  path: string;
  added: number;
  removed: number;
  ops: DiffOp[];
  running?: boolean;
  defaultOpen?: boolean;
}

const LIVE_CHANGE: Record<string, string> = { Edit: 'Editing', Create: 'Creating', Patch: 'Patching' };

/** One file's change: verb, path, counts; the caret previews 14 lines in a ToolPanel. */
export function DiffCard({ verb = 'Edit', path, added, removed, ops, running = false, defaultOpen = false }: DiffCardProps) {
  const [open, setOpen] = useState(defaultOpen);
  const preview = ops.slice(0, 14);
  const more = ops.length - preview.length;
  return (
    <div>
      <div className="ds-diff-head">
        <button type="button" className="ds-tool-toggle" aria-expanded={open} onClick={() => setOpen((v) => !v)}>
          <span className={running ? 'ds-shimmer ds-tool-live' : 'ds-diff-verb'}>{running ? LIVE_CHANGE[verb] : verb}</span>
          <span className="ds-diff-path" title={path}>
            {path}
          </span>
          <Caret open={open} />
        </button>
        <span className="ds-spacer" />
        <ChangeCount tone="add" value={added} />
        <ChangeCount tone="del" value={removed} />
      </div>
      <Expand open={open}>
        <ToolPanel className="ds-diff-panel">
          <div className="ds-diff-scroll">
            <DiffLines ops={preview} />
            {more > 0 && <div className="ds-diff-more">+{more} more lines</div>}
          </div>
        </ToolPanel>
      </Expand>
    </div>
  );
}

/** "Edited 3 files · 5 edits" with the turn's counts; opens to its DiffCards. */
export function DiffGroup({ label, added, removed, defaultOpen = false, children }: { label: string; added: number; removed: number; defaultOpen?: boolean; children: ReactNode }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div>
      <div className="ds-diff-head">
        <button type="button" className="ds-tool-toggle" aria-expanded={open} onClick={() => setOpen((v) => !v)}>
          <span className="ds-diff-group-label">{label}</span>
          <Caret open={open} />
        </button>
        <span className="ds-spacer" />
        <ChangeCount tone="add" value={added} />
        <ChangeCount tone="del" value={removed} />
      </div>
      <Expand open={open}>
        <div className="ds-diff-group-body">{children}</div>
      </Expand>
    </div>
  );
}

/* Transcript: messages ------------------------------------------------------ */

/** The user's prompt: right-aligned, up to 80% of the column, the tail corner tight. */
export function UserBubble({ children }: { children: ReactNode }) {
  return (
    <div className="ds-user-turn">
      <div className="ds-user-bubble">{children}</div>
    </div>
  );
}

/** The agent's reply: prose at 14/22, primary text, no bubble. */
export function AssistantText({ children }: { children: ReactNode }) {
  return <div className="ds-assistant">{children}</div>;
}

/* Composer ------------------------------------------------------------------ */

export type SendState = 'empty' | 'ready' | 'running' | 'starting';

/** The 32px round send: ArrowUp, Stop while the agent runs, the spinner while it starts. */
export function SendButton({ state = 'ready', onClick }: { state?: SendState; onClick?: () => void }) {
  if (state === 'starting')
    return (
      <span className="ds-send" data-starting aria-label="Starting">
        <Spinner />
      </span>
    );
  if (state === 'running')
    return (
      <button type="button" className="ds-send" aria-label="Stop" onClick={onClick}>
        <Square size={14} fill="currentColor" strokeWidth={0} />
      </button>
    );
  return (
    <button type="button" className="ds-send" aria-label="Send" disabled={state === 'empty'} onClick={onClick}>
      <ArrowUp size={16} strokeWidth={2} />
    </button>
  );
}

export type Autonomy = 'off' | 'low' | 'medium' | 'high';
const AUTONOMY: Record<Autonomy, { label: string; icon: IconName }> = {
  off: { label: 'Supervised', icon: 'supervised' },
  low: { label: 'Auto-accept edits', icon: 'accept-edits' },
  medium: { label: 'Auto', icon: 'auto-approve' },
  high: { label: 'Full access', icon: 'full-access' },
};

/** A chip in the row under the composer: rounded-full for autonomy, rounded-md for model and reasoning. */
export function ComposerChip({ round = false, open = false, children, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { round?: boolean; open?: boolean }) {
  return (
    <button type="button" aria-expanded={open} {...props} className={cx('ds-composer-chip', round && 'ds-composer-chip-round', props.className)}>
      {children}
    </button>
  );
}

export interface ComposerProps {
  /** The draft; empty shows the placeholder. */
  value?: string;
  placeholder?: string;
  /** home: a new chat's taller field with the + and send under the text. */
  layout?: 'row' | 'home';
  send?: SendState;
  autonomy?: Autonomy;
  model?: string;
  provider?: Provider;
  reasoning?: 'off' | 'low' | 'medium' | 'high' | 'ultra';
  /** Attachment chips above the draft, such as <FileChips />. */
  attachments?: ReactNode;
  focused?: boolean;
}

export function Composer({
  value = '',
  placeholder = 'What would you like to work on?  (/ for skills, @ for files)',
  layout = 'row',
  send,
  autonomy = 'medium',
  model = 'Claude Opus 4.5',
  provider = 'anthropic',
  reasoning = 'high',
  attachments,
  focused = false,
}: ComposerProps) {
  const sendState = send ?? (value ? 'ready' : 'empty');
  const mode = AUTONOMY[autonomy];
  return (
    <div className="ds-composer-stack">
      <div className="ds-composer" data-layout={layout} data-focused={focused || undefined}>
        {attachments !== undefined && <div className="ds-composer-attachments">{attachments}</div>}
        <div className="ds-composer-field" data-empty={!value || undefined}>
          {value || placeholder}
          {focused && <span className="ds-composer-caret" aria-hidden="true" />}
        </div>
        <div className="ds-composer-add">
          <button type="button" className="ds-composer-plus" aria-label="Add files or a plugin">
            <Icon name="plus" />
          </button>
        </div>
        <div className="ds-composer-send">
          <SendButton state={sendState} />
        </div>
      </div>
      <div className="ds-composer-bar">
        <ComposerChip round aria-label={'Autonomy: ' + mode.label}>
          <Icon name={mode.icon} size={14} strokeWidth={2.29} />
          <span className="ds-truncate">{mode.label}</span>
        </ComposerChip>
        <div className="ds-composer-models">
          <ComposerChip aria-label={'Model: ' + model}>
            <ModelIcon provider={provider} />
            <span className="ds-truncate">{model}</span>
          </ComposerChip>
          <ComposerChip aria-label={'Reasoning: ' + reasoning}>
            <Icon name="brain" size={14} />
            <span className={cx('ds-capitalize', reasoning === 'ultra' && 'ds-ultra')}>{reasoning}</span>
          </ComposerChip>
        </div>
      </div>
    </div>
  );
}

/* Sidebar ------------------------------------------------------------------- */

export interface SessionRowProps {
  title: string;
  /** "2m", "1h", "3d": right-aligned in a 32px column. */
  time?: string;
  status?: SessionStatus;
  active?: boolean;
  unread?: boolean;
  /** The harness mark on the trailing edge; hover swaps it for the … menu. */
  provider?: Provider;
  onClick?: () => void;
}

/** A chat in the sidebar: a 14px status slot, the title, the time and the harness mark. */
export function SessionRow({ title, time, status, active = false, unread = false, provider = 'factory', onClick }: SessionRowProps) {
  const lead = status === 'working' ? <Spinner size={14} /> : status && status !== 'ready' ? <StatusGlyph status={status} /> : null;
  return (
    <div className="ds-session">
      <button type="button" className="ds-session-row" data-active={active || undefined} data-unread={unread || undefined} aria-current={active || undefined} onClick={onClick}>
        <span className="ds-session-lead">{lead}</span>
        {unread && <span className="ds-sr-only">Unread:</span>}
        <span className="ds-session-title">{title}</span>
        <span className="ds-session-trail">
          <span className={cx('ds-session-time', status === 'approval' && 'ds-session-time-warning')}>{time}</span>
          <span className="ds-session-mark">
            <ModelIcon provider={provider} muted />
          </span>
        </span>
      </button>
      <button type="button" className="ds-session-menu" aria-label={'Actions for ' + title}>
        <Icon name="ellipsis" />
      </button>
    </div>
  );
}

/** A fold heading in the sidebar list: label-size, muted, a caret that turns open. */
export function SidebarHeading({ label, open = true, count, onToggle, action }: { label: string; open?: boolean; count?: number; onToggle?: () => void; action?: ReactNode }) {
  return (
    <div className="ds-sidebar-heading">
      <h3 className="ds-sidebar-heading-title">
        <button type="button" className="ds-sidebar-heading-button" aria-expanded={open} onClick={onToggle}>
          <span className="ds-truncate">{label}</span>
          <ChevronRight size={14} strokeWidth={1.5} className="ds-sidebar-heading-caret" data-open={open || undefined} aria-hidden="true" />
          {!open && count !== undefined && <span className="ds-sidebar-heading-count">{count}</span>}
        </button>
      </h3>
      {action}
    </div>
  );
}

/** A workspace in the sidebar: folder, name, and a + for a new chat on hover. */
export function WorkspaceRow({ name, open = true, onAdd }: { name: string; open?: boolean; onAdd?: () => void }) {
  return (
    <div className="ds-workspace-row">
      <button type="button" className="ds-workspace-name" aria-expanded={open}>
        <span className="ds-workspace-icon">
          <Icon name={open ? 'folder-open' : 'folder'} />
        </span>
        <span className="ds-truncate">{name}</span>
      </button>
      <button type="button" className="ds-workspace-add" aria-label={'New chat in ' + name} onClick={onAdd}>
        <Icon name="plus" size={14} />
      </button>
    </div>
  );
}

/* Window chrome ------------------------------------------------------------- */

/** A header tab: 28px, 208px wide, active takes the active fill and 500 weight. */
export function HeaderTab({ label, icon = 'square-pen', active = false, live = false, onClose }: { label: string; icon?: IconName; active?: boolean; live?: boolean; onClose?: () => void }) {
  return (
    <div className="ds-header-tab" data-active={active || undefined}>
      <button type="button" role="tab" aria-selected={active} className="ds-header-tab-button">
        <span className="ds-header-tab-icon">{live ? <Spinner size={13} /> : <Icon name={icon} size={14} />}</span>
        <span className="ds-truncate">{label}</span>
      </button>
      <button type="button" className="ds-header-tab-close" aria-label={'Close ' + label} onClick={onClose}>
        <Icon name="x" size={12} />
      </button>
    </div>
  );
}

/** The macOS window controls, inset in the 36px titlebar strip. */
export function WindowControls() {
  return (
    <span className="ds-window-controls" aria-hidden="true">
      <span style={{ background: 'var(--ds-window-close)' }} />
      <span style={{ background: 'var(--ds-window-minimize)' }} />
      <span style={{ background: 'var(--ds-window-zoom)' }} />
    </span>
  );
}

files.tokens.css:
/* Silkscreen: SIL Open Font License 1.1. The DROIDEX wordmark face; the UI and code use the system faces, as in the app. */
@font-face {
  font-family: 'Silkscreen';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}


html,
body {
  min-height: 100%;
}
body {
  margin: 0;
  background: var(--ds-canvas);
  color: var(--ds-fg);
  font-family: var(--ds-font-sans);
  font-size: 13px;
  line-height: 18px;
  letter-spacing: -0.08px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
h1, h2, h3, h4, p, pre {
  margin: 0;
}
h1, h2, h3, h4 {
  font-family: var(--ds-font-heading);
  font-weight: 600;
  color: var(--ds-fg);
  text-wrap: balance;
}
code, pre, kbd, samp {
  font-family: var(--ds-font-mono);
}
::selection {
  background: color-mix(in srgb, var(--ds-accent) 22%, transparent);
}
/* Keyboard focus only: a click never draws a ring. */
:focus {
  outline: none;
}
:focus-visible {
  outline: 1.5px solid var(--ds-focus);
}
:where(button, a[href], summary, select, [role='tab'], [role='menuitem'], [role='switch']) {
  cursor: pointer;
}
:where(button:disabled) {
  cursor: not-allowed;
}
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--ds-fg) 16%, transparent);
  border-radius: 9999px;
}

/* Type: one class sets size, leading, tracking and weight (tailwind fontSize on origin/main). */
.ds-wordmark { font-family: var(--ds-font-pixel); font-size: 32px; line-height: 32px; letter-spacing: -0.04em; font-weight: 400; }
.ds-display { font-size: 24px; line-height: 30px; letter-spacing: -0.48px; font-weight: 600; }
.ds-title { font-size: 22px; line-height: 28px; letter-spacing: -0.44px; font-weight: 600; }
.ds-heading { font-size: 18px; line-height: 22px; letter-spacing: -0.27px; font-weight: 600; }
.ds-subheading { font-size: 16px; line-height: 20px; letter-spacing: -0.16px; font-weight: 600; }
.ds-prose { font-size: 14px; line-height: 22px; letter-spacing: -0.15px; font-weight: 400; text-wrap: pretty; }
.ds-body-lg { font-size: 14px; line-height: 20px; letter-spacing: -0.15px; font-weight: 400; }
.ds-body { font-size: 13px; line-height: 18px; letter-spacing: -0.08px; font-weight: 400; }
.ds-body-strong { font-size: 13px; line-height: 18px; letter-spacing: -0.08px; font-weight: 500; }
.ds-label { font-size: 12px; line-height: 16px; letter-spacing: 0; font-weight: 500; }
.ds-caption { font-size: 11px; line-height: 16px; letter-spacing: 0.06px; font-weight: 400; }
.ds-overline { font-size: 10px; line-height: 12px; letter-spacing: 0.8px; font-weight: 500; text-transform: uppercase; }
.ds-code { font-family: var(--ds-font-mono); font-size: var(--ds-text-code); line-height: 1.5; letter-spacing: 0; font-weight: 400; }
.ds-code-sm { font-family: var(--ds-font-mono); font-size: 11px; line-height: 16px; letter-spacing: 0; font-weight: 400; }
.ds-tabular { font-variant-numeric: tabular-nums; }
.ds-text-primary { color: var(--ds-fg); }
.ds-text-secondary { color: var(--ds-fg-secondary); }
.ds-text-muted { color: var(--ds-fg-muted); }
.ds-text-quiet { color: var(--ds-fg-quiet); }
.ds-truncate { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-capitalize { text-transform: capitalize; }
.ds-ultra { color: var(--ds-ultra); }
.ds-spacer { flex: 1; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.ds-invisible { visibility: hidden; }
.ds-icon { flex-shrink: 0; }

/* Brand */
.ds-brandmark { display: inline-block; font-family: var(--ds-font-pixel); font-weight: 400; line-height: 1; white-space: nowrap; user-select: none; }

/* Live work shimmers; it stops the moment work stops. */
.ds-shimmer {
  background: linear-gradient(90deg, var(--ds-fg-muted) 0%, var(--ds-fg) 50%, var(--ds-fg-muted) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: ds-shimmer 1.8s linear infinite;
}
.ds-skeleton {
  border-radius: var(--ds-radius-sm);
  background: linear-gradient(90deg, var(--ds-elevated) 25%, var(--ds-active) 50%, var(--ds-elevated) 75%);
  background-size: 200% 100%;
  animation: ds-shimmer 1.6s ease-in-out infinite;
}
.ds-spin { animation: ds-spin 1s linear infinite; }
.ds-spin-slow { animation: ds-spin 1.8s linear infinite; transform-origin: center; }

/* Button (ui/Button) */
.ds-button {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 64px;
  box-sizing: border-box;
  border: 0;
  border-radius: var(--ds-radius-md);
  font-family: var(--ds-font-sans);
  font-size: 13px;
  line-height: 18px;
  font-weight: 500;
  letter-spacing: -0.08px;
  white-space: nowrap;
  user-select: none;
  transition: background-color 150ms ease-out, color 150ms ease-out, opacity 150ms ease-out, transform 150ms ease-out;
}
.ds-button-sm { height: var(--ds-control-sm); padding: 0 10px; font-size: 12px; line-height: 16px; letter-spacing: 0; }
.ds-button-md { height: var(--ds-control-md); padding: 0 12px; }
.ds-button-lg { height: var(--ds-control-lg); padding: 0 12px; }
.ds-button-icon { min-width: 0; padding: 0; }
.ds-button-icon.ds-button-sm { width: var(--ds-control-sm); }
.ds-button-icon.ds-button-md { width: var(--ds-control-md); }
.ds-button-icon.ds-button-lg { width: var(--ds-control-lg); }
.ds-button-round { border-radius: 9999px; }
.ds-button:active:not(:disabled) { transform: scale(0.97); transition-duration: 75ms; }
.ds-button:disabled { opacity: 0.4; cursor: not-allowed; }
.ds-button-glyph { display: inline-flex; flex-shrink: 0; width: 16px; height: 16px; }
.ds-button-glyph svg { width: 100%; height: 100%; }
.ds-button-label { overflow: hidden; text-overflow: ellipsis; }
.ds-button-spinner { position: absolute; inset: 0; display: grid; place-items: center; }
.ds-button-primary { background: var(--ds-fg); color: var(--ds-canvas); }
.ds-button-secondary { background: var(--ds-elevated); color: var(--ds-fg-secondary); }
.ds-button-secondary[aria-pressed='true'] { background: var(--ds-active); color: var(--ds-fg); }
.ds-button-ghost { background: transparent; color: var(--ds-fg-muted); }
.ds-button-ghost:is([aria-pressed='true'], [aria-expanded='true'], [data-selected]) { color: var(--ds-fg); }
.ds-button-danger { background: var(--ds-danger-soft); color: var(--ds-danger); }
.ds-button-success { background: var(--ds-positive-soft); color: var(--ds-positive); }

/* Badge (ui/Badge) */
.ds-badge {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 4px;
  height: 20px;
  box-sizing: border-box;
  padding: 0 8px;
  border-radius: 9999px;
  font-size: 11px;
  line-height: 16px;
  font-weight: 500;
  letter-spacing: 0.06px;
  white-space: nowrap;
  user-select: none;
}
.ds-badge-overline { height: 18px; padding: 0 6px; border-radius: var(--ds-radius-xs); font-size: 10px; line-height: 12px; letter-spacing: 0.8px; text-transform: uppercase; }
.ds-badge-neutral { background: var(--ds-elevated); color: var(--ds-fg-secondary); }
.ds-badge-success { background: var(--ds-positive-soft); color: var(--ds-positive); }
.ds-badge-warning { background: var(--ds-warning-soft); color: var(--ds-warning); }
.ds-badge-danger { background: var(--ds-danger-soft); color: var(--ds-danger); }
.ds-badge-accent { background: var(--ds-accent-soft); color: var(--ds-accent); }

/* Card */
.ds-card { display: flex; flex-direction: column; box-sizing: border-box; padding: 16px; border-radius: var(--ds-radius-xl); background: var(--ds-surface); color: var(--ds-fg); overflow: hidden; }
.ds-card-floating { background: var(--ds-raised); box-shadow: var(--ds-shadow-md); }

/* Field (ui/Field): filled, never outlined. */
.ds-field { display: flex; flex-direction: column; gap: 6px; }
.ds-field-label { font-size: 12px; line-height: 16px; font-weight: 500; color: var(--ds-fg-secondary); user-select: none; }
.ds-input-wrap { position: relative; display: flex; align-items: center; }
.ds-input-icon { position: absolute; left: 10px; color: var(--ds-fg-muted); pointer-events: none; }
.ds-input {
  width: 100%;
  min-width: 0;
  height: var(--ds-control-lg);
  box-sizing: border-box;
  padding: 0 12px;
  border: 0;
  border-radius: var(--ds-radius-md);
  background: var(--ds-field);
  color: var(--ds-fg);
  font-family: var(--ds-font-sans);
  font-size: 14px;
  line-height: 20px;
  letter-spacing: -0.15px;
  transition: background-color 150ms ease-out;
}
.ds-input-compact { height: var(--ds-control-md); padding: 0 8px; font-size: 13px; letter-spacing: -0.08px; }
.ds-input-affixed { padding-left: 30px; }
.ds-input::placeholder { color: var(--ds-fg-muted); opacity: 1; }
.ds-input[aria-invalid='true'] { background: var(--ds-danger-soft); }
.ds-input[aria-invalid='true']:focus-visible { outline-color: var(--ds-danger); }
.ds-input:disabled { opacity: 0.4; cursor: not-allowed; }
.ds-field-hint, .ds-field-error { font-size: 11px; line-height: 16px; letter-spacing: 0.06px; color: var(--ds-fg-muted); }
.ds-field-error { color: var(--ds-danger); }

/* Switch */
.ds-switch { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 16px; padding: 0; border: 0; background: transparent; color: var(--ds-fg); font-family: var(--ds-font-sans); text-align: left; user-select: none; }
.ds-switch:disabled { opacity: 0.4; }
.ds-switch-text { display: flex; min-width: 0; flex-direction: column; gap: 2px; }
.ds-switch-label { font-size: 13px; line-height: 18px; letter-spacing: -0.08px; }
.ds-switch-description { font-size: 11px; line-height: 16px; letter-spacing: 0.06px; color: var(--ds-fg-muted); }
.ds-switch-track { position: relative; flex-shrink: 0; width: 32px; height: 20px; border-radius: 9999px; background: var(--ds-active); transition: background-color 150ms ease-out; }
.ds-switch-thumb { position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 9999px; background: var(--ds-fg-muted); transition: transform 250ms var(--ds-ease), background-color 150ms ease-out; }
.ds-switch[aria-checked='true'] .ds-switch-track { background: var(--ds-fg); }
.ds-switch[aria-checked='true'] .ds-switch-thumb { background: var(--ds-canvas); transform: translateX(12px); }

/* Tabs: a segmented control. */
.ds-tablist { display: inline-flex; gap: 2px; padding: 2px; border-radius: var(--ds-radius-md); background: var(--ds-elevated); }
.ds-tab { display: inline-flex; align-items: center; height: 24px; padding: 0 10px; border: 0; border-radius: var(--ds-radius-sm); background: transparent; color: var(--ds-fg-muted); font-family: var(--ds-font-sans); font-size: 12px; line-height: 16px; font-weight: 500; white-space: nowrap; user-select: none; transition: background-color 150ms ease-out, color 150ms ease-out; }
.ds-tab[aria-selected='true'] { background: var(--ds-active); color: var(--ds-fg); }
.ds-tab:disabled { opacity: 0.4; }
.ds-tabpanel { padding-top: 16px; }

/* Dialog */
.ds-dialog { width: min(var(--ds-dialog-form), calc(100% - 32px)); max-height: calc(100% - 64px); box-sizing: border-box; margin: auto; padding: 24px; overflow: auto; border: 0; border-radius: var(--ds-radius-2xl); background: var(--ds-raised); color: var(--ds-fg); box-shadow: var(--ds-shadow-md); }
.ds-dialog-confirm { width: min(var(--ds-dialog-confirm), calc(100% - 32px)); }
.ds-dialog-content { width: min(var(--ds-dialog-content), calc(100% - 32px)); }
.ds-dialog[open] { animation: ds-dialog-in 180ms var(--ds-ease); }
.ds-dialog::backdrop { background: var(--ds-backdrop); }
.ds-dialog-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.ds-dialog-heading { min-width: 0; }
.ds-dialog-description { margin-top: 4px; font-size: 14px; line-height: 20px; letter-spacing: -0.15px; color: var(--ds-fg-secondary); }
.ds-dialog-close { margin: -4px -8px 0 0; }
.ds-dialog-body { margin-top: 12px; }
.ds-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 24px; }

/* Row and SectionHeader (ui/Row): in a 8px gutter, text lands on the 20px content edge. */
.ds-gutter { display: flex; flex-direction: column; padding: 0 8px; }
.ds-row { display: flex; width: 100%; box-sizing: border-box; align-items: center; gap: 10px; padding: 8px 12px; border: 0; border-radius: var(--ds-radius-md); background: transparent; color: var(--ds-fg); font-family: var(--ds-font-sans); font-size: 13px; line-height: 18px; letter-spacing: -0.08px; text-align: left; }
.ds-row-button { user-select: none; transition: background-color 150ms ease-out; }
.ds-row-button[data-active] { background: var(--ds-active); }
.ds-row-button:disabled { opacity: 0.4; }
.ds-row-icon { display: flex; flex-shrink: 0; align-items: center; justify-content: center; width: 16px; height: 16px; color: var(--ds-fg-muted); transition: color 150ms ease-out; }
.ds-row-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-row-meta { flex-shrink: 0; font-size: 11px; line-height: 16px; letter-spacing: 0.06px; color: var(--ds-fg-muted); font-variant-numeric: tabular-nums; }
.ds-section-header { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding: 16px 12px 4px; user-select: none; }
.ds-section-header-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; line-height: 16px; font-weight: 500; color: var(--ds-fg-muted); }
.ds-section-header-trailing { flex-shrink: 0; font-size: 11px; line-height: 16px; color: var(--ds-fg-muted); font-variant-numeric: tabular-nums; }

/* Menu (ui/Menu): 12px container, 6px pad, 8px items. Groups part by space. */
.ds-menu { display: flex; flex-direction: column; min-width: 200px; max-width: 320px; box-sizing: border-box; padding: 6px; border-radius: var(--ds-radius-lg); background: var(--ds-raised); color: var(--ds-fg); box-shadow: var(--ds-shadow-md); transform-origin: top left; animation: ds-pop-in 150ms var(--ds-ease); }
.ds-menu-group { display: flex; flex-direction: column; }
.ds-menu-group + .ds-menu-group { margin-top: 6px; }
.ds-menu-label { padding: 6px 8px 4px; font-size: 11px; line-height: 16px; color: var(--ds-fg-muted); user-select: none; }
.ds-menu-item { display: flex; width: 100%; min-height: 30px; flex-shrink: 0; align-items: center; gap: 8px; padding: 6px 8px; box-sizing: border-box; border: 0; border-radius: var(--ds-radius-md); background: transparent; color: var(--ds-fg); font-family: var(--ds-font-sans); font-size: 13px; line-height: 18px; letter-spacing: -0.08px; text-align: left; user-select: none; }
.ds-menu-item[data-described] { align-items: flex-start; }
.ds-menu-item:focus-visible { outline: none; background: var(--ds-elevated); }
.ds-menu-item:disabled { opacity: 0.4; }
.ds-menu-item-icon { display: flex; flex-shrink: 0; width: 16px; height: 18px; align-items: center; color: var(--ds-fg-muted); }
.ds-menu-item-text { display: flex; flex: 1; min-width: 0; flex-direction: column; }
.ds-menu-item-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-menu-item-description { font-size: 11px; line-height: 16px; letter-spacing: 0.06px; color: var(--ds-fg-muted); }
.ds-menu-item-shortcut { flex-shrink: 0; font-size: 11px; line-height: 18px; color: var(--ds-fg-muted); font-variant-numeric: tabular-nums; }
.ds-menu-item-check { margin-top: 2px; color: var(--ds-fg-secondary); }
.ds-menu-item[data-danger], .ds-menu-item[data-danger] .ds-menu-item-icon { color: var(--ds-danger); }
.ds-menu-item[data-danger]:focus-visible { background: var(--ds-danger-soft); }
.ds-menu-item[data-blink='on'] { background: var(--ds-elevated); }
.ds-menu-item[data-blink='off'] { background: transparent !important; }

.ds-kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 18px; height: 18px; box-sizing: border-box; padding: 0 6px; border-radius: var(--ds-radius-xs); background: color-mix(in srgb, var(--ds-canvas) 70%, transparent); color: var(--ds-fg-secondary); font-family: var(--ds-font-sans); font-size: 11px; line-height: 16px; }

/* Toast: colour lives only in the 16px status icon. */
.ds-toast { display: flex; width: 356px; max-width: 100%; box-sizing: border-box; align-items: flex-start; gap: 10px; padding: 12px 12px 12px 14px; border-radius: var(--ds-radius-lg); background: var(--ds-raised); color: var(--ds-fg); box-shadow: var(--ds-shadow-md); animation: ds-rise-in 250ms var(--ds-ease); }
.ds-toast-icon { margin-top: 1px; }
.ds-toast-icon-success { color: var(--ds-positive); }
.ds-toast-icon-danger { color: var(--ds-danger); }
.ds-toast-icon-warning { color: var(--ds-warning); }
.ds-toast-icon-update { color: var(--ds-link); }
.ds-toast-icon-loading { color: var(--ds-fg-muted); }
.ds-toast-body { flex: 1; min-width: 0; }
.ds-toast-title { font-size: 13px; line-height: 18px; font-weight: 500; letter-spacing: -0.08px; }
.ds-toast-description { margin-top: 2px; font-size: 12px; line-height: 16px; color: var(--ds-fg-secondary); }
.ds-toast-action, .ds-toast-close { display: inline-flex; flex-shrink: 0; align-items: center; justify-content: center; height: 24px; border: 0; border-radius: var(--ds-radius-sm); font-family: var(--ds-font-sans); user-select: none; transition: background-color 150ms ease-out, color 150ms ease-out; }
.ds-toast-action { padding: 0 8px; background: var(--ds-elevated); color: var(--ds-fg); font-size: 12px; line-height: 16px; font-weight: 500; }
.ds-toast-close { width: 24px; margin-right: -4px; background: transparent; color: var(--ds-fg-muted); }

/* Model marks and status glyphs */
.ds-model-icon { flex-shrink: 0; }

/* Transcript: disclosure (transcript/primitives) */
.ds-caret { flex-shrink: 0; color: var(--ds-fg-muted); opacity: 0; transition: transform 150ms ease-out, opacity 150ms ease-out; }
.ds-caret[data-always] { opacity: 1; }
.ds-caret[data-open] { opacity: 1; transform: rotate(90deg); }
:is(.ds-tool-line, .ds-diff-head, .ds-worked-toggle):is(:hover, :focus-within) .ds-caret { opacity: 1; }
.ds-expand { display: grid; grid-template-rows: 0fr; overflow: hidden; opacity: 0; pointer-events: none; transition: grid-template-rows 240ms var(--ds-ease), opacity 240ms var(--ds-ease); }
.ds-expand[data-open] { grid-template-rows: 1fr; opacity: 1; pointer-events: auto; }
.ds-expand-inner { min-height: 0; overflow: hidden; transform: translateY(-6px); transition: transform 200ms var(--ds-ease); }
.ds-expand[data-open] > .ds-expand-inner { transform: none; }
.ds-tool-panel { overflow: hidden; border-radius: var(--ds-radius-lg); background: color-mix(in srgb, var(--ds-elevated) 50%, transparent); }

/* Transcript: a tool call is one sentence. */
.ds-tool { min-width: 0; }
.ds-tool-line { display: flex; min-width: 0; align-items: center; gap: 6px; font-size: 13px; line-height: 18px; letter-spacing: -0.08px; }
button.ds-tool-line { width: 100%; padding: 0; border: 0; background: none; color: inherit; font-family: inherit; text-align: left; }
.ds-tool-toggle { display: flex; min-width: 0; align-items: center; gap: 6px; padding: 0; border: 0; background: none; color: inherit; font: inherit; letter-spacing: inherit; text-align: left; }
.ds-tool-verb { flex-shrink: 0; color: var(--ds-fg-secondary); }
.ds-tool-live { flex-shrink: 0; font-weight: 500; }
.ds-tool-target { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-tool-dir { color: color-mix(in srgb, var(--ds-fg-muted) 50%, transparent); }
.ds-tool-name { color: var(--ds-fg-muted); transition: color 150ms ease-out; }
.ds-tool-source { flex-shrink: 0; color: color-mix(in srgb, var(--ds-fg-muted) 60%, transparent); }
.ds-tool-body { padding: 6px 0 0 20px; }
.ds-tool-card { padding: 10px 14px; font-family: var(--ds-font-mono); font-size: var(--ds-text-code); line-height: 1.5; }
.ds-tool-args { white-space: pre-wrap; word-break: break-word; color: var(--ds-fg); }
.ds-tool-prompt { color: var(--ds-fg-muted); user-select: none; }
.ds-tool-output { max-height: 224px; overflow: auto; white-space: pre-wrap; word-break: break-word; color: var(--ds-fg-muted); }
.ds-tool-args + .ds-tool-output { margin-top: 8px; }
.ds-tool-output-error { color: var(--ds-danger); }
.ds-file-rail { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.ds-file-chip { display: inline-flex; height: var(--ds-control-sm); align-items: center; gap: 6px; padding: 0 10px; border: 0; border-radius: 9999px; background: color-mix(in srgb, var(--ds-elevated) 50%, transparent); color: var(--ds-fg-secondary); font-family: var(--ds-font-sans); font-size: 12px; line-height: 16px; font-weight: 500; transition: background-color 150ms ease-out, color 150ms ease-out; }
.ds-file-chip-name { max-width: 160px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-thinking-label { color: var(--ds-fg-muted); transition: color 150ms ease-out; }
.ds-thinking-body { padding: 8px 0 0 20px; font-size: 13px; line-height: 18px; letter-spacing: -0.08px; color: var(--ds-fg-quiet); white-space: pre-wrap; }
.ds-working { display: flex; height: 20px; align-items: center; font-size: 13px; line-height: 18px; letter-spacing: -0.08px; animation: ds-cue-in 160ms ease-out both; }
.ds-worked { padding-bottom: 6px; border-bottom: 1px solid var(--ds-border); }
.ds-worked-toggle { display: flex; height: var(--ds-control-sm); align-items: center; gap: 4px; padding: 0; border: 0; background: none; color: var(--ds-fg-quiet); font-family: var(--ds-font-sans); font-size: 14px; line-height: 20px; letter-spacing: -0.15px; transition: color 150ms ease-out; }
.ds-worked-toggle .ds-caret { color: inherit; }
.ds-worked-body { display: flex; flex-direction: column; gap: 10px; padding: 12px 0 0 20px; }

/* Transcript: diffs */
.ds-diff-head { display: flex; min-width: 0; align-items: center; gap: 6px; font-size: 13px; line-height: 18px; letter-spacing: -0.08px; }
.ds-diff-verb { flex-shrink: 0; font-weight: 500; color: var(--ds-fg-secondary); }
.ds-diff-path { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; line-height: 16px; letter-spacing: 0.06px; color: var(--ds-fg-muted); }
.ds-diff-group-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; color: var(--ds-fg-muted); }
.ds-diff-group-body { display: flex; flex-direction: column; gap: 10px; padding: 8px 0 0 20px; }
.ds-change-count { flex-shrink: 0; font-size: 11px; line-height: 16px; letter-spacing: 0.06px; font-variant-numeric: tabular-nums; }
.ds-change-add { color: var(--ds-diff-add-fg); }
.ds-change-del { color: var(--ds-diff-del-fg); }
.ds-diff-panel { margin-top: 6px; }
.ds-diff-scroll { max-height: 224px; overflow: auto; padding: 4px 0; }
.ds-diff-lines { min-width: max-content; font-family: var(--ds-font-mono); font-size: var(--ds-text-code); line-height: 1.5; }
.ds-diff-row { display: flex; border-left: 2px solid transparent; }
.ds-diff-add { background: var(--ds-diff-add-bg); }
.ds-diff-del { background: var(--ds-diff-del-bg); }
.ds-diff-sign { width: 20px; flex-shrink: 0; text-align: center; color: var(--ds-fg-muted); user-select: none; }
.ds-diff-add .ds-diff-sign { color: var(--ds-diff-add-fg); }
.ds-diff-del .ds-diff-sign { color: var(--ds-diff-del-fg); }
.ds-diff-text { flex: 1; padding: 0 4px; white-space: pre; color: var(--ds-fg-secondary); }
.ds-diff-more { padding: 6px 12px; background: color-mix(in srgb, var(--ds-canvas) 40%, transparent); font-size: 11px; line-height: 16px; color: var(--ds-fg-muted); }

/* Transcript: messages (column: 672px, 16px between items) */
.ds-transcript { display: flex; width: 100%; max-width: var(--ds-reading-width); margin: 0 auto; flex-direction: column; gap: 16px; }
.ds-user-turn { display: flex; justify-content: flex-end; }
.ds-user-bubble { max-width: 80%; box-sizing: border-box; padding: 10px 16px; border-radius: var(--ds-radius-xl) var(--ds-radius-xl) var(--ds-radius-xs) var(--ds-radius-xl); background: var(--ds-prompt-bubble); color: var(--ds-fg); font-size: 14px; line-height: 22px; letter-spacing: -0.15px; white-space: pre-wrap; overflow-wrap: anywhere; }
.ds-assistant { color: var(--ds-fg); font-size: 14px; line-height: 22px; letter-spacing: -0.15px; text-wrap: pretty; }
.ds-assistant p + p, .ds-assistant p + ul, .ds-assistant ul + p { margin-top: 12px; }
.ds-assistant ul { margin: 0; padding-left: 20px; }
.ds-assistant code { padding: 1px 4px; border-radius: var(--ds-radius-xs); background: var(--ds-code-bg); font-size: 12px; }

/* Composer (PromptInput) */
.ds-composer-stack { display: flex; flex-direction: column; }
.ds-composer { position: relative; z-index: 1; border-radius: var(--ds-radius-xl); background: var(--ds-elevated); }
.ds-composer[data-focused] { background-image: linear-gradient(color-mix(in srgb, var(--ds-fg) 5%, transparent), color-mix(in srgb, var(--ds-fg) 5%, transparent)); }
.ds-composer-attachments { display: flex; flex-wrap: wrap; gap: 6px; padding: 12px 12px 0; }
.ds-composer-attachments .ds-file-rail { margin-top: 0; }
.ds-composer-attachments .ds-file-chip { background: color-mix(in srgb, var(--ds-active) 60%, transparent); }
.ds-composer-field { min-height: 52px; box-sizing: border-box; padding: 16px 50px 16px 44px; color: var(--ds-fg); font-size: 14px; line-height: 20px; white-space: pre-wrap; }
.ds-composer-field[data-empty] { color: color-mix(in srgb, var(--ds-fg-muted) 50%, transparent); }
.ds-composer[data-layout='home'] .ds-composer-field { min-height: 112px; padding: 16px 16px 56px; }
.ds-composer-caret { display: inline-block; width: 1.5px; height: 17px; margin-left: 1px; vertical-align: -3px; background: var(--ds-fg); animation: ds-caret-blink 1s steps(1) infinite; }
.ds-composer-add { position: absolute; bottom: 12px; left: 8px; display: flex; }
.ds-composer-plus { display: flex; width: var(--ds-control-sm); height: var(--ds-control-sm); align-items: center; justify-content: center; border: 0; border-radius: var(--ds-radius-md); background: transparent; color: var(--ds-fg-muted); transition: background-color 150ms ease-out, color 150ms ease-out; }
.ds-composer-send { position: absolute; right: 10px; bottom: 10px; }
.ds-send { display: flex; width: 32px; height: 32px; flex-shrink: 0; align-items: center; justify-content: center; border: 0; border-radius: 9999px; background: var(--ds-fg); color: var(--ds-canvas); transition: opacity 150ms ease-out; }
.ds-send:disabled { opacity: 0.4; }
.ds-send[data-starting] { opacity: 0.9; }
.ds-composer-bar { display: flex; min-width: 0; align-items: center; gap: 4px; padding: 8px 0 0 10px; font-size: 12px; line-height: 16px; }
.ds-composer-models { display: flex; flex-shrink: 0; align-items: center; gap: 4px; margin-left: auto; }
.ds-composer-chip { display: flex; min-width: 0; height: var(--ds-control-sm); flex-shrink: 0; align-items: center; gap: 6px; padding: 0 6px; border: 0; border-radius: var(--ds-radius-md); background: transparent; color: var(--ds-fg-secondary); font-family: var(--ds-font-sans); font-size: 12px; line-height: 16px; transition: background-color 150ms ease-out, color 150ms ease-out; }
.ds-composer-chip-round { flex-shrink: 1; padding: 0 10px; border-radius: 9999px; font-size: 11px; letter-spacing: 0.06px; }
.ds-composer-chip[aria-expanded='true'] { background: var(--ds-active); color: var(--ds-fg); }

/* Sidebar (Sidebar, SidebarSessionRow, SidebarSectionHeading) */
.ds-sidebar { display: flex; width: var(--ds-sidebar-width); height: 100%; flex-shrink: 0; flex-direction: column; background: var(--ds-sidebar); }
.ds-titlebar { display: flex; height: 36px; flex-shrink: 0; align-items: center; padding-left: 14px; }
.ds-window-controls { display: inline-flex; gap: 8px; }
.ds-window-controls > span { width: 12px; height: 12px; border-radius: 9999px; }
.ds-session { position: relative; }
.ds-session-row { display: flex; width: 100%; box-sizing: border-box; align-items: center; gap: 10px; padding: 8px 12px; border: 0; border-radius: var(--ds-radius-md); background: transparent; font-family: var(--ds-font-sans); text-align: left; transition: background-color 150ms ease-out; }
.ds-session-row[data-active] { background: var(--ds-active); }
.ds-session-lead { display: flex; width: 14px; flex-shrink: 0; align-items: center; justify-content: center; color: var(--ds-fg-secondary); }
.ds-session-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; line-height: 18px; letter-spacing: -0.08px; color: var(--ds-fg-secondary); transition: color 150ms ease-out; }
.ds-session-row:is([data-active], [data-unread]) .ds-session-title { color: var(--ds-fg); }
.ds-session-row[data-unread]:not([data-active]) .ds-session-title { font-weight: 600; }
.ds-session-row[data-active] .ds-session-lead { color: var(--ds-fg); }
.ds-session-trail { display: flex; flex-shrink: 0; align-items: center; gap: 8px; margin-left: 4px; }
.ds-session-time { width: 32px; text-align: right; font-size: 11px; line-height: 16px; letter-spacing: 0.06px; color: var(--ds-fg-muted); font-variant-numeric: tabular-nums; }
.ds-session-time-warning { color: var(--ds-warning); }
.ds-session-mark { display: flex; transition: opacity 150ms ease-out; }
.ds-session-menu { position: absolute; top: 50%; right: 6px; display: flex; width: 24px; height: 24px; align-items: center; justify-content: center; border: 0; border-radius: var(--ds-radius-sm); background: transparent; color: var(--ds-fg-muted); opacity: 0; transform: translateY(-50%); transition: opacity 150ms ease-out, background-color 150ms ease-out, color 150ms ease-out; }
.ds-session:is(:hover, :focus-within) .ds-session-menu { opacity: 1; }
.ds-session:is(:hover, :focus-within) .ds-session-mark { opacity: 0; }
.ds-sidebar-heading { display: flex; align-items: center; gap: 4px; padding: 4px 10px 4px 12px; }
.ds-sidebar-heading-title { min-width: 0; flex: 1; margin: 0; font: inherit; }
.ds-sidebar-heading-button { display: flex; width: 100%; align-items: center; gap: 4px; padding: 0; border: 0; border-radius: var(--ds-radius-sm); background: none; color: var(--ds-fg-muted); font-family: var(--ds-font-sans); font-size: 12px; line-height: 16px; font-weight: 500; text-align: left; transition: color 150ms ease-out; }
.ds-sidebar-heading-caret { flex-shrink: 0; opacity: 0.5; transition: transform 150ms ease-out, opacity 150ms ease-out; }
.ds-sidebar-heading-caret[data-open] { transform: rotate(90deg); }
.ds-sidebar-heading-count { margin-left: auto; font-size: 11px; font-weight: 400; opacity: 0.7; font-variant-numeric: tabular-nums; }
.ds-workspace-row { display: flex; align-items: center; gap: 4px; padding: 6px 10px 6px 12px; }
.ds-workspace-name { display: flex; min-width: 0; flex: 1; align-items: center; gap: 10px; padding: 0; border: 0; border-radius: var(--ds-radius-sm); background: none; color: var(--ds-fg); font-family: var(--ds-font-sans); font-size: 13px; line-height: 18px; letter-spacing: -0.08px; text-align: left; }
.ds-workspace-icon { display: flex; color: var(--ds-fg-muted); transition: color 150ms ease-out; }
.ds-workspace-add { display: flex; padding: 2px; border: 0; border-radius: var(--ds-radius-sm); background: none; color: transparent; transition: color 150ms ease-out; }
.ds-workspace-row:hover .ds-workspace-add { color: var(--ds-fg-muted); }
.ds-workspace-add:focus-visible { color: var(--ds-fg); }

/* Header tabs (HeaderTabs): 36px strip, 28px tabs */
.ds-header { display: flex; height: 36px; flex-shrink: 0; align-items: center; gap: 4px; padding-right: 12px; }
.ds-header-tab { position: relative; display: flex; width: 208px; min-width: 128px; height: var(--ds-control-sm); align-items: center; border-radius: var(--ds-radius-md); color: var(--ds-fg-muted); transition: background-color 150ms ease-out, color 150ms ease-out; }
.ds-header-tab[data-active] { background: var(--ds-active); color: var(--ds-fg); }
.ds-header-tab-button { display: flex; min-width: 0; height: 100%; flex: 1; align-items: center; gap: 6px; padding: 0 10px; border: 0; border-radius: var(--ds-radius-md); background: none; color: inherit; font-family: var(--ds-font-sans); font-size: 13px; line-height: 18px; letter-spacing: -0.08px; text-align: left; }
.ds-header-tab[data-active] .ds-header-tab-button { padding-right: 28px; font-weight: 500; }
.ds-header-tab-icon { display: flex; width: 14px; flex-shrink: 0; justify-content: center; }
.ds-header-tab-close { position: absolute; top: 50%; right: 4px; display: flex; width: 20px; height: 20px; align-items: center; justify-content: center; border: 0; border-radius: var(--ds-radius-xs); background: none; color: var(--ds-fg-muted); opacity: 0; transform: translateY(-50%); transition: opacity 150ms ease-out, background-color 150ms ease-out; }
.ds-header-tab:is([data-active], :hover, :focus-within) .ds-header-tab-close { opacity: 1; }

/* Hover lives only where hovering exists. */
@media (hover: hover) {
  .ds-button-primary:hover:not(:disabled) { opacity: 0.9; }
  .ds-button-secondary:hover:not(:disabled) { background: var(--ds-active); color: var(--ds-fg); }
  .ds-button-ghost:hover:not(:disabled) { background: var(--ds-elevated); color: var(--ds-fg-secondary); }
  .ds-button-danger:hover:not(:disabled) { background: var(--ds-danger); color: var(--ds-canvas); }
  .ds-button-success:hover:not(:disabled) { background: var(--ds-positive); color: var(--ds-canvas); }
  .ds-input:hover:not(:disabled):not(:focus):not([aria-invalid='true']) { background: var(--ds-active); }
  .ds-tab:hover:not(:disabled):not([aria-selected='true']) { color: var(--ds-fg-secondary); }
  .ds-row-button:hover:not(:disabled):not([data-active]) { background: var(--ds-elevated); }
  .ds-row-button:hover:not(:disabled) .ds-row-icon { color: var(--ds-fg-secondary); }
  .ds-menu-item:hover:not(:disabled) { background: var(--ds-elevated); }
  .ds-menu-item[data-danger]:hover:not(:disabled) { background: var(--ds-danger-soft); }
  .ds-toast-action:hover { background: var(--ds-active); }
  .ds-toast-close:hover { background: var(--ds-elevated); color: var(--ds-fg); }
  .ds-tool-toggle:hover .ds-tool-name { color: var(--ds-fg); }
  .ds-tool-toggle:hover .ds-thinking-label { color: var(--ds-fg-secondary); }
  .ds-file-chip:hover { background: var(--ds-elevated); color: var(--ds-fg); }
  .ds-worked-toggle:hover { color: var(--ds-fg-secondary); }
  .ds-composer-plus:hover { background: color-mix(in srgb, var(--ds-active) 60%, transparent); color: var(--ds-fg); }
  .ds-composer-chip:hover:not([aria-expanded='true']) { background: color-mix(in srgb, var(--ds-active) 60%, transparent); color: var(--ds-fg); }
  .ds-send:hover:not(:disabled) { opacity: 0.9; }
  .ds-session-row:hover:not([data-active]) { background: var(--ds-elevated); }
  .ds-session-row:hover .ds-session-title, .ds-session-row:hover .ds-session-lead { color: var(--ds-fg); }
  .ds-session-menu:hover { background: var(--ds-active); color: var(--ds-fg); }
  .ds-sidebar-heading-button:hover { color: var(--ds-fg-secondary); }
  .ds-sidebar-heading-button:hover .ds-sidebar-heading-caret { opacity: 1; }
  .ds-workspace-row:hover .ds-workspace-icon { color: var(--ds-fg-secondary); }
  .ds-workspace-add:hover { color: var(--ds-fg) !important; }
  .ds-header-tab:not([data-active]):hover { background: var(--ds-elevated); color: var(--ds-fg); }
  .ds-header-tab-close:hover { background: var(--ds-active); color: var(--ds-fg); }
}

@keyframes ds-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
@keyframes ds-spin { to { transform: rotate(360deg); } }
@keyframes ds-dialog-in { from { opacity: 0; transform: scale(0.96); } }
@keyframes ds-pop-in { from { opacity: 0; transform: translateY(-4px) scale(0.98); } }
@keyframes ds-rise-in { from { opacity: 0; transform: translateY(8px); } }
@keyframes ds-cue-in { from { opacity: 0; } }
@keyframes ds-caret-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.15; } }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0ms !important;
    animation-duration: 0ms !important;
    animation-iteration-count: 1 !important;
  }
}

