import { useState } from 'react';
import { BrandMark, Button, Row, SessionRow, SidebarHeading, StatusGlyph, WindowControls, WorkspaceRow } from '@droidex/design-system';

const CHATS = [
  { id: 'a', title: 'Harden auto-compaction lifecycle', time: '', status: 'working' as const, provider: 'factory' as const },
  { id: 'b', title: 'Shrink the composer context ring', time: '4m', status: 'approval' as const, provider: 'claude' as const, unread: true },
  { id: 'c', title: 'Fix sidebar marquee fade', time: '1h', status: 'reply' as const, provider: 'factory' as const, unread: true },
  { id: 'd', title: 'Port icons to @droidex/icons', time: '3h', provider: 'openai' as const },
  { id: 'e', title: 'Flaky child-session smoke test', time: '1d', status: 'failed' as const, provider: 'factory' as const },
];

export default function SidebarExample() {
  const [active, setActive] = useState('d');
  const [open, setOpen] = useState(true);
  return (
    <main className="flex h-screen bg-[color:var(--ds-canvas)]">
      <aside className="ds-sidebar">
        <div className="ds-titlebar">
          <WindowControls />
        </div>
        <div className="flex items-center justify-between px-3 pb-1 pt-0.5">
          <BrandMark size={13} className="pl-2" />
          <div className="flex items-center gap-0.5">
            <Button variant="ghost" size="sm" icon="search" aria-label="Search chats, messages, and PRs" />
            <Button variant="ghost" size="sm" icon="list-filter" aria-label="Show unread only" />
          </div>
        </div>
        <div className="px-2 pb-1.5">
          <div className="relative">
            <Row icon="square-pen" label="New chat" onClick={() => setActive('')} />
            <div className="absolute right-1.5 top-1/2 -translate-y-1/2">
              <Button variant="ghost" size="sm" icon="message-circle-plus" aria-label="New chat without a workspace" />
            </div>
          </div>
          <Row icon="git-pull-request" label="Pull requests" onClick={() => setActive('')} />
          <Row icon={<StatusGlyph status="ready" decorative />} label="Projects" onClick={() => setActive('')} />
          <Row icon="clock" label="Automations" onClick={() => setActive('')} />
        </div>
        <div className="min-h-0 flex-1 overflow-hidden px-2">
          <div className="space-y-3">
            <div>
              <WorkspaceRow name="droidex" />
              <SidebarHeading label="Chats" open={open} count={CHATS.length} onToggle={() => setOpen((v) => !v)} />
              {open &&
                CHATS.map((chat) => (
                  <SessionRow
                    key={chat.id}
                    title={chat.title}
                    time={chat.time}
                    status={chat.status}
                    unread={chat.unread}
                    provider={chat.provider}
                    active={active === chat.id}
                    onClick={() => setActive(chat.id)}
                  />
                ))}
            </div>
          </div>
        </div>
        <div className="px-2 pb-2 pt-4">
          <Row icon="settings" label="Settings" onClick={() => setActive('')} />
        </div>
      </aside>
      <div className="flex flex-1 flex-col justify-center gap-3 px-10">
        <p className="ds-label ds-text-muted">Leading slot, 14px</p>
        <div className="flex flex-col gap-2 ds-body ds-text-secondary">
          {(['working', 'approval', 'reply', 'failed', 'settled'] as const).map((s) => (
            <div key={s} className="flex items-center gap-2.5">
              <StatusGlyph status={s} />
              <span>{({ working: 'Working', approval: 'Needs approval', reply: 'Replied', failed: 'Failed', settled: 'Settled' } as const)[s]}</span>
            </div>
          ))}
        </div>
        <p className="ds-caption ds-text-muted mt-2 max-w-[220px]">Hover a chat: the harness mark gives way to its … menu. Titles sit on the 46px line.</p>
      </div>
    </main>
  );
}

